  useEffect(() => {
    if (!accessToken) return;
    if (!isWindowActive || !isPageVisible) return;

    // Keep realtime dashboard streaming only on highest-value tabs.
    const realtimeTabs = new Set(["overview", "payments", "notifications"]);
    if (!realtimeTabs.has(activeTab)) return;

    let closed = false;
    let reconnectTimer: number | null = null;
    let abortController: AbortController | null = null;
    let reconnectAttempt = 0;

    const parseAndApplySseEvent = (rawChunk: string) => {
      const normalized = rawChunk.replace(/\r/g, "");
      const lines = normalized.split("\n");
      let eventType = "message";
      const dataLines: string[] = [];

      for (const line of lines) {
        if (!line || line.startsWith(":")) continue;
        if (line.startsWith("event:")) {
          eventType = line.slice("event:".length).trim();
          continue;
        }
        if (line.startsWith("data:")) {
          dataLines.push(line.slice("data:".length).trim());
        }
      }

      if (dataLines.length === 0) return;

      const payloadText = dataLines.join("\n");
      if (eventType === "dashboard") {
        try {
          const payload = JSON.parse(payloadText) as DashboardData;
          setDashboard(payload);
          const streamCurrency = String(payload?.stats?.payments?.dashboardCurrency || "").trim().toUpperCase();
          if (streamCurrency) {
            setCurrency(streamCurrency);
          }
        } catch {
          // Ignore malformed payloads and wait for next valid event.
        }
      } else if (eventType === "error") {
        try {
          const payload = JSON.parse(payloadText) as { message?: string };
          if (payload?.message) {
            setStatus(`Dashboard stream warning: ${payload.message}`);
          }
        } catch {
          // Ignore malformed error payloads.
        }
      }
    };

    const scheduleReconnect = () => {
      if (closed) return;
      const base = Math.min(15000, 1000 * Math.pow(2, reconnectAttempt));
      const jitter = Math.floor(Math.random() * 500);
      const delayMs = base + jitter;
      reconnectAttempt += 1;
      reconnectTimer = window.setTimeout(() => {
        void connectStream();
      }, delayMs);
    };

    const connectStream = async () => {
      if (closed) return;
      if (document.visibilityState !== "visible") {
        scheduleReconnect();
        return;
      }

      try {
        abortController = new AbortController();
        const response = await fetch(`${API_BASE_URL}/business/dashboard/stream`, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${accessToken}`,
            Accept: "text/event-stream"
          },
          credentials: "include",
          signal: abortController.signal
        });

        if (!response.ok) {
          throw new Error(`Dashboard stream request failed (${response.status})`);
        }
        if (!response.body) {
          throw new Error("Dashboard stream response has no body");
        }

        reconnectAttempt = 0;
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = "";

        while (!closed) {
          const { done, value } = await reader.read();
          if (done) {
            throw new Error("Dashboard stream closed");
          }
          if (!value) continue;

          buffer += decoder.decode(value, { stream: true });
          let boundary = buffer.indexOf("\n\n");
          while (boundary !== -1) {
            const rawChunk = buffer.slice(0, boundary);
            buffer = buffer.slice(boundary + 2);
            parseAndApplySseEvent(rawChunk);
            boundary = buffer.indexOf("\n\n");
          }
        }
      } catch (err: any) {
        if (closed || err?.name === "AbortError") return;
        scheduleReconnect();
      }
    };

    void connectStream();

    return () => {
      closed = true;
      if (reconnectTimer !== null) {
        window.clearTimeout(reconnectTimer);
      }
      abortController?.abort();
    };
  }, [accessToken, activeTab, isWindowActive, isPageVisible]);

  // Read saved integration configs into state
  useEffect(() => {
    if (integrationSectionTab !== "calls") return;
    
    const emailInt = integrations.find(i => i.provider === "email");
    if (emailInt) {
      if (emailInt.hasToken && !emailApiKey) setEmailApiKey("********");
      const config: any = emailInt.config || {};
      if (config.email && !emailFrom) setEmailFrom(config.email);
    }

    const smsInt = integrations.find(i => i.provider === "sms");
    if (smsInt) {
      if (smsInt.hasToken && !smsAccountSid) setSmsAccountSid("********");
      const config: any = smsInt.config || {};
      if (config.authToken && !smsAuthToken) setSmsAuthToken("********");
      if (config.phoneNumber && !smsPhoneNumber) setSmsPhoneNumber(config.phoneNumber);
    }

    const waInt = integrations.find(i => i.provider === "whatsapp");
    if (waInt) {
      if (waInt.hasToken && !whatsappAccountSid) setWhatsappAccountSid("********");
      const config: any = waInt.config || {};
      if (config.authToken && !whatsappAuthToken) setWhatsappAuthToken("********");
      if (config.whatsappNumber && !whatsappNumber) setWhatsappNumber(waInt?.config?.whatsappNumber || "");
    }
  }, [integrationSectionTab, integrations]);

