  const runNativeMigration = async () => {
    if (!accessToken) return;
    try {
      setRunningNativeMigration(true);
      const candidateKeys = Array.isArray(nativeMigrationPreview?.pendingTemplateKeys)
        ? nativeMigrationPreview.pendingTemplateKeys
        : [];
      const response = await apiRequest<{ installed: Array<{ key: string }>; skipped: Array<{ key: string }> }>(
        "/business/native/migrations/run",
        {
          method: "POST",
          accessToken,
          csrfToken,
          body: { templateKeys: candidateKeys }
        }
      );
      const installedCount = Array.isArray(response.installed) ? response.installed.length : 0;
      const skippedCount = Array.isArray(response.skipped) ? response.skipped.length : 0;
      setStatus(`Migration complete: ${installedCount} installed, ${skippedCount} skipped`);
      await loadNativeAutomationData();
    } catch (err: any) {
      setStatus(err?.response?.data?.error || err?.message || "Failed to run native migration");
    } finally {
      setRunningNativeMigration(false);
    }
  };

  const getMarketplacePayloadError = (
    provider: string,
    payload: Record<string, string | undefined>
  ) => {
    const providerKey = String(provider || "").trim().toLowerCase();
    if (providerKey === "shopify") {
      if (!payload.shopDomain) return "Shopify domain is required";
      return null;
    }
    if (providerKey === "woocommerce") {
      if (!payload.storeUrl) return "WooCommerce store URL is required";
      if (!payload.consumerKey) return "WooCommerce consumer key is required";
      if (!payload.consumerSecret) return "WooCommerce consumer secret is required";
      return null;
    }
    if (providerKey === "meta_ads") {
      if (!payload.adAccountId) return "Meta ad account ID is required";
      if (!payload.accessToken) return "Meta access token is required";
      return null;
    }
    if (providerKey === "google_ads") {
      if (!payload.customerId) return "Google Ads customer ID is required";
      if (!payload.developerToken) return "Google Ads developer token is required";
      if (!payload.clientId) return "Google OAuth client ID is required";
      if (!payload.clientSecret) return "Google OAuth client secret is required";
      if (!payload.refreshToken) return "Google OAuth refresh token is required";
      return null;
    }
    if (providerKey === "zapier") {
      if (!payload.webhookUrl) return "Zapier webhook URL is required";
      if (payload.retryAttempts) {
        const retry = Number(payload.retryAttempts);
        if (!Number.isFinite(retry) || retry < 1 || retry > 10) {
          return "Zapier retry attempts must be between 1 and 10";
        }
      }
      return null;
    }
    if (providerKey === "hubspot") {
      if (!payload.accessToken) return "HubSpot private app token is required";
      return null;
    }
    if (providerKey === "amazon") {
      if (!payload.sellerId) return "Amazon seller ID is required";
      if (!payload.marketplaceId) return "Amazon marketplace ID is required";
      if (!payload.lwaClientId) return "Amazon LWA client ID is required";
      if (!payload.lwaClientSecret) return "Amazon LWA client secret is required";
      if (!payload.refreshToken) return "Amazon refresh token is required";
      if (!payload.awsAccessKeyId) return "AWS access key ID is required";
      if (!payload.awsSecretAccessKey) return "AWS secret access key is required";
      return null;
    }
    if (providerKey === "cjdropshipping") {
      if (!payload.apiBaseUrl) return "CJ API base URL is required";
      if (!payload.accessToken) return "CJ access token is required";
      return null;
    }
    if (providerKey === "aliexpress") {
      if (!payload.apiBaseUrl) return "AliExpress API base URL is required";
      if (!payload.accessToken) return "AliExpress access token is required";
      return null;
    }
    if (providerKey === "paypal") {
      if (!payload.clientId) return "PayPal client ID is required";
      if (!payload.clientSecret) return "PayPal client secret is required";
      return null;
    }
    if (providerKey === "stripe_tax") {
      if (!payload.secretKey) return "Stripe secret key is required";
      return null;
    }
    if (providerKey === "taxjar") {
      if (!payload.apiKey) return "TaxJar API key is required";
      return null;
    }
    if (providerKey === "shippo") {
      if (!payload.apiToken) return "Shippo API token is required";
      return null;
    }
    if (providerKey === "easypost") {
      if (!payload.apiKey) return "EasyPost API key is required";
      return null;
    }
    if (providerKey === "sift") {
      if (!payload.accountId) return "Sift account ID is required";
      if (!payload.apiKey) return "Sift API key is required";
      return null;
    }
    if (providerKey === "klaviyo") {
      if (!payload.apiKey) return "Klaviyo API key is required";
      return null;
    }
    if (providerKey === "zendesk") {
      if (!payload.subdomain) return "Zendesk subdomain is required";
      if (!payload.email) return "Zendesk email is required";
      if (!payload.apiToken) return "Zendesk API token is required";
      return null;
    }
    if (providerKey === "gorgias") {
      if (!payload.domain) return "Gorgias domain is required";
      if (!payload.email) return "Gorgias email is required";
      if (!payload.apiKey) return "Gorgias API key is required";
      return null;
    }
    if (providerKey === "quickbooks") {
      if (!payload.realmId) return "QuickBooks realm ID is required";
      if (!payload.accessToken) return "QuickBooks access token is required";
      return null;
    }
    if (providerKey === "xero") {
      if (!payload.tenantId) return "Xero tenant ID is required";
      if (!payload.accessToken) return "Xero access token is required";
      return null;
    }
    if (providerKey === "loopreturns") {
      if (!payload.accessToken) return "Loop Returns access token is required";
      return null;
    }
    if (providerKey === "algolia") {
      if (!payload.appId) return "Algolia app ID is required";
      if (!payload.apiKey) return "Algolia API key is required";
      return null;
    }
    if (providerKey === "ga4") {
      if (!payload.measurementId) return "GA4 measurement ID is required";
      if (!payload.apiSecret) return "GA4 API secret is required";
      return null;
    }
    return "Unsupported integration provider";
  };

  const setupMarketplaceIntegration = async (template: any) => {
    if (!accessToken) {
      setStatus("Not authenticated");
      return;
    }
    const provider = String(template?.provider || "").trim().toLowerCase();
    const name = String(template?.name || provider || "integration");
    if (!provider) {
      setStatus("Invalid integration provider");
      return;
    }

    const payload = getMarketplacePayload(provider);
    const payloadError = getMarketplacePayloadError(provider, payload);
    if (payloadError) {
      setStatus(payloadError);
      return;
    }

    try {
      setSettingUpMarketplaceProvider(provider);
      if (provider === "shopify" && !payload.accessToken) {
        const startResponse = await apiRequest<{ authUrl?: string }>("/business/integrations/shopify/oauth/start", {
          method: "POST",
          accessToken,
          csrfToken,
          body: { shopDomain: payload.shopDomain }
        });
        const authUrl = String(startResponse?.authUrl || "").trim();
        if (!authUrl) {
          throw new Error("Failed to start Shopify OAuth");
        }
        window.location.assign(authUrl);
        return;
      }

      const response = await apiRequest<{ integration?: any }>(`/business/integrations/${provider}/setup`, {
        method: "POST",
        accessToken,
        csrfToken,
        body: payload
      });
      const result = response?.integration || null;
      const normalizedStatus = String(result?.status || "").toLowerCase();
      if (normalizedStatus === "connected") {
        setStatus(`${name} connected successfully`);
      } else if (normalizedStatus === "requested") {
        setStatus(`${name} setup request submitted`);
      } else if (normalizedStatus === "failed") {
        setStatus(`${name} setup failed`);
      } else {
        setStatus(`${name} setup completed`);
      }
      if (
        provider === "zapier" ||
        provider === "hubspot" ||
        provider === "shopify" ||
        provider === "woocommerce" ||
        provider === "meta_ads" ||
        provider === "google_ads" ||
        provider === "amazon" ||
        provider === "cjdropshipping" ||
        provider === "aliexpress" ||
        provider === "paypal" ||
        provider === "stripe_tax" ||
        provider === "taxjar" ||
        provider === "shippo" ||
        provider === "easypost" ||
        provider === "sift" ||
        provider === "klaviyo" ||
        provider === "zendesk" ||
        provider === "gorgias" ||
        provider === "quickbooks" ||
        provider === "xero" ||
        provider === "loopreturns" ||
        provider === "algolia" ||
        provider === "ga4"
      ) {
        setMarketplaceConfigByProvider((prev) => {
          const current = prev[provider] || {};
          const next = { ...prev };
          if (provider === "zapier") {
            next[provider] = {
              ...current,
              signingSecret: ""
            };
          } else if (provider === "hubspot") {
            next[provider] = {
              ...current,
              accessToken: ""
            };
          } else if (provider === "shopify") {
            next[provider] = { ...current, accessToken: "" };
          } else if (provider === "woocommerce") {
            next[provider] = { ...current, consumerSecret: "" };
          } else if (provider === "meta_ads") {
            next[provider] = { ...current, accessToken: "" };
          } else if (provider === "google_ads") {
            next[provider] = {
              ...current,
              developerToken: "",
              clientSecret: "",
              refreshToken: ""
            };
          } else if (provider === "amazon") {
            next[provider] = {
              ...current,
              lwaClientSecret: "",
              refreshToken: "",
              awsSecretAccessKey: ""
            };
          } else if (provider === "paypal") {
            next[provider] = {
              ...current,
              clientSecret: ""
            };
          } else if (provider === "stripe_tax") {
            next[provider] = {
              ...current,
              secretKey: ""
            };
          } else if (provider === "taxjar") {
            next[provider] = {
              ...current,
              apiKey: ""
            };
          } else if (provider === "shippo") {
            next[provider] = {
              ...current,
              apiToken: ""
            };
          } else if (provider === "easypost" || provider === "klaviyo") {
            next[provider] = {
              ...current,
              apiKey: ""
            };
          } else if (provider === "sift") {
            next[provider] = {
              ...current,
              apiKey: ""
            };
          } else if (provider === "zendesk") {
            next[provider] = {
              ...current,
              apiToken: ""
            };
          } else if (provider === "gorgias") {
            next[provider] = {
              ...current,
              apiKey: ""
            };
          } else if (provider === "quickbooks" || provider === "xero") {
            next[provider] = {
              ...current,
              accessToken: ""
            };
          } else if (provider === "loopreturns") {
            next[provider] = {
              ...current,
              accessToken: ""
            };
          } else if (provider === "algolia") {
            next[provider] = {
              ...current,
              apiKey: ""
            };
          } else if (provider === "ga4") {
            next[provider] = {
              ...current,
              apiSecret: ""
            };
          } else {
            next[provider] = {
              ...current,
              accessToken: "",
              appSecret: ""
            };
          }
          return next;
        });
      }
      await loadData();
    } catch (err: any) {
      setStatus(err?.response?.data?.error || err?.message || "Failed to setup integration");
    } finally {
      setSettingUpMarketplaceProvider(null);
    }
  };

  const syncMarketplaceInventory = async (template: any, dryRun = false) => {
    if (!accessToken) {
      setStatus("Not authenticated");
      return;
    }
    const provider = String(template?.provider || "").trim().toLowerCase();
    if (!["amazon", "cjdropshipping", "aliexpress"].includes(provider)) {
      setStatus("This provider does not support supplier inventory sync");
      return;
    }
    try {
      setSyncingMarketplaceProvider(provider);
      const result = await apiRequest<{ summary?: any }>(`/business/integrations/${provider}/inventory-sync`, {
        method: "POST",
        accessToken,
        csrfToken,
        body: {
          dryRun,
          shopId: selectedShopId || undefined
        }
      });
      const summary = result?.summary || {};
      setStatus(
        `${template?.name || provider}: synced ${summary.updated || 0} updated, ${summary.unchanged || 0} unchanged, ${summary.failed || 0} failed`
      );
      await loadData();
    } catch (err: any) {
      setStatus(err?.response?.data?.error || err?.message || "Failed to sync supplier inventory");
    } finally {
      setSyncingMarketplaceProvider(null);
    }
  };

