      setShopGrowthInsights(insightsData || null);
      setShopGrowthAudiences(Array.isArray(audiencesData.audiences) ? audiencesData.audiences : []);
      setShopCatalogPreview(Array.isArray(catalogData.preview) ? catalogData.preview : []);
